/* ============================================================
   application dugumu > Style > Custom CSS  (Ders 9.9)
   akis-uret.py bu dosyayi application dugumune gomer.

   Salt okunur tablolar (formio datagrid, anahtari "tablo"):
   devre disi input'lar varsayilan olarak gri kutu gorunur ve dar
   kolonlarda metni keser (orn. "01.10.2026 17:38" -> "01.10.2026").
   Asagidaki kurallar hucreyi duz metin gibi gosterir ve kolonu
   icerige gore genisletir (field-sizing: content, Chromium 123+).
   Canli sayfada denenip dogrulandi.
   ============================================================ */

.formio-component-tablo table { table-layout: auto; width: auto; min-width: 100%; }
.formio-component-tablo thead th { white-space: nowrap; background: #f4f7f9; }
.formio-component-tablo td { padding: 6px 10px !important; vertical-align: middle; }

.formio-component-tablo input.form-control,
.formio-component-tablo input.form-control:disabled,
.formio-component-tablo input.form-control[readonly] {
  field-sizing: content;
  min-width: 3ch;
  width: auto;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  color: #212529 !important;
  opacity: 1 !important;
  padding: 0 !important;
  height: auto;
  cursor: default;
}

/* Indirme baglantisi uyari kutusunda belirgin olsun */
.alert a[href^="/indir/"] { text-decoration: underline; }

